import json
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional

import requests


SUPABASE_URL_ENV = "SUPABASE_URL"
SUPABASE_KEY_ENV = "SUPABASE_SERVICE_ROLE_KEY"


@dataclass
class UpsertResult:
    document: Dict[str, Any]
    status_code: int
    inserted: bool


def _get_env(name: str) -> str:
    value = os.getenv(name)
    if not value:
        raise ValueError(f"Missing required environment variable: {name}")
    return value


def _normalize_document(document: Dict[str, Any], primary_key: str) -> Dict[str, Any]:
    if not isinstance(document, dict):
        raise TypeError("document must be a JSON object")
    if primary_key not in document:
        raise ValueError(f"document must contain primary key field '{primary_key}'")
    return document


def upsert_document(
    document: Dict[str, Any],
    table: str,
    primary_key: str = "id",
    schema: str = "public",
    returning: str = "representation",
) -> UpsertResult:
    normalized = _normalize_document(document, primary_key)
    base_url = _get_env(SUPABASE_URL_ENV).rstrip("/")
    api_key = _get_env(SUPABASE_KEY_ENV)
    url = f"{base_url}/rest/v1/{table}"
    headers = {
        "apikey": api_key,
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Prefer": f"resolution=merge-duplicates,return={returning}",
    }
    params = {"on_conflict": primary_key, "select": "*", "schema": schema}
    response = requests.post(url, headers=headers, params=params, data=json.dumps(normalized), timeout=30)
    response.raise_for_status()
    payload: Any = response.json() if response.content else normalized
    if isinstance(payload, list):
        payload = payload[0] if payload else normalized
    inserted = response.status_code in (201, 200) and response.headers.get("Preference-Applied", "").find("resolution=merge-duplicates") == -1
    return UpsertResult(document=payload if isinstance(payload, dict) else normalized, status_code=response.status_code, inserted=inserted)


def upsert_document_from_json(
    document_json: str,
    table: str,
    primary_key: str = "id",
    schema: str = "public",
) -> UpsertResult:
    return upsert_document(json.loads(document_json), table=table, primary_key=primary_key, schema=schema)

import os
from typing import Any, Dict, List, Optional

import boto3
from boto3.dynamodb.conditions import Attr, Key


class QueryDocumentsError(Exception):
    pass


def _table_name() -> str:
    name = os.environ.get("AWS_DYNAMODB_TABLE_NAME") or os.environ.get("DYNAMODB_TABLE_NAME")
    if not name:
        raise QueryDocumentsError("Missing table name")
    return name


def _table():
    region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")
    kwargs: Dict[str, Any] = {}
    if region:
        kwargs["region_name"] = region
    resource = boto3.resource("dynamodb", **kwargs)
    return resource.Table(_table_name())


def query_documents(
    field_name: str,
    field_value: Any,
    *,
    partition_key_name: Optional[str] = None,
    limit: Optional[int] = None,
    consistent_read: bool = False,
) -> List[Dict[str, Any]]:
    table = _table()
    if partition_key_name and field_name == partition_key_name:
        kwargs: Dict[str, Any] = {
            "KeyConditionExpression": Key(field_name).eq(field_value),
            "ConsistentRead": consistent_read,
        }
        if limit is not None:
            kwargs["Limit"] = limit
        response = table.query(**kwargs)
        return response.get("Items", [])

    kwargs = {
        "FilterExpression": Attr(field_name).eq(field_value),
        "ConsistentRead": consistent_read,
    }
    if limit is not None:
        kwargs["Limit"] = limit
    response = table.scan(**kwargs)
    return response.get("Items", [])


def main() -> None:
    import argparse
    import json

    parser = argparse.ArgumentParser(description="Query documents from Amazon DynamoDB")
    parser.add_argument("field_name")
    parser.add_argument("field_value")
    parser.add_argument("--partition-key-name")
    parser.add_argument("--limit", type=int)
    parser.add_argument("--consistent-read", action="store_true")
    args = parser.parse_args()
    result = query_documents(
        args.field_name,
        args.field_value,
        partition_key_name=args.partition_key_name,
        limit=args.limit,
        consistent_read=args.consistent_read,
    )
    print(json.dumps(result, default=str))


if __name__ == "__main__":
    main()

